import React, { useState, useEffect, useMemo } from 'react';
import { useTable, useSortBy } from 'react-table';
import { searchTracks, getTrackWithGenre } from '../services/api';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';

const TrackSearch = ({ searchTerm, onShowSimilarTracks }) => {
  const [filteredTracks, setFilteredTracks] = useState([]);
  const [trackDetails, setTrackDetails] = useState({});

  useEffect(() => {
    if (searchTerm) {
      searchTracks(searchTerm).then(async tracks => {
        setFilteredTracks(tracks);

        // Fetch detailed info including genres for each track
        const detailsPromises = tracks.map(track =>
          getTrackWithGenre(track.id).then(details => ({ [track.id]: details }))
        );
        const detailsArray = await Promise.all(detailsPromises);
        setTrackDetails(Object.assign({}, ...detailsArray));
      }).catch(error => console.error('Error fetching tracks:', error));
    }
  }, [searchTerm]);

  const columns = useMemo(() => [
    { Header: 'Track Name', accessor: 'name', width: 80 },
    { Header: 'Artist Name', accessor: 'artists[0].name', width: 80 },
    { Header: 'Album Name', accessor: 'album.name', width: 80 },
    { Header: 'Release Date', accessor: 'album.release_date', width: 80, Cell: ({ value }) => value ? value.split('-')[0] : 'Unknown' },
    { Header: 'Genre', accessor: 'genre', width: 80, Cell: ({ row }) => {
        const details = trackDetails[row.original.id];
        return details ? details.genres?.join(', ') || 'N/A' : 'Loading...';
      }
    },
    { Header: 'Tempo', accessor: 'tempo', width: 80, Cell: ({ row }) => trackDetails[row.original.id]?.tempo || 'Loading...' },
    { Header: 'Key', accessor: 'key', width: 80, Cell: ({ row }) => trackDetails[row.original.id]?.key || 'Loading...' },
    { Header: 'Energy', accessor: 'energy', width: 80, Cell: ({ row }) => trackDetails[row.original.id]?.energy || 'Loading...' },
    { Header: 'Danceability', accessor: 'danceability', width: 80, Cell: ({ row }) => trackDetails[row.original.id]?.danceability || 'Loading...' },
    { Header: 'Preview', accessor: 'preview', width: 80, Cell: ({ row }) => row.original.id ? (
        <iframe
          src={`https://open.spotify.com/embed/track/${row.original.id}`}
          width="100%"
          height="80"
          allow="encrypted-media"
          style={{ border: 'none' }}
        ></iframe>
      ) : 'No Preview'
    },
  ], [trackDetails]);

  const data = useMemo(() => filteredTracks, [filteredTracks]);
  const { getTableProps, getTableBodyProps, headerGroups, rows, prepareRow } = useTable({ columns, data }, useSortBy);

  return filteredTracks.length > 0 ? (
    <table {...getTableProps()} style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse' }} className="results-table">
      <thead>
        {headerGroups.map(headerGroup => (
          <tr {...headerGroup.getHeaderGroupProps()} style={{ backgroundColor: '#00b4db', color: 'white' }}>
            {headerGroup.headers.map(column => (
              <th {...column.getHeaderProps(column.getSortByToggleProps())} style={{ padding: '10px', borderBottom: '1px solid #ddd', width: column.width }}>
                {column.render('Header')}
                {column.isSorted ? (column.isSortedDesc ? <ArrowDownwardIcon /> : <ArrowUpwardIcon />) : null}
              </th>
            ))}
          </tr>
        ))}
      </thead>
      <tbody {...getTableBodyProps()}>
        {rows.map((row, index) => {
          prepareRow(row);
          return (
            <tr
              {...row.getRowProps()}
              style={{
                backgroundColor: index % 2 === 0 ? '#f9f9f9' : 'white',
                color: '#606060',
                fontFamily: 'Arial, sans-serif',
                borderBottom: '1px solid #ddd'
              }}
            >
              {row.cells.map(cell => (
                <td {...cell.getCellProps()} style={{ padding: '10px', borderBottom: '1px solid #ddd' }}>
                  {cell.render('Cell')}
                </td>
              ))}
            </tr>
          );
        })}
      </tbody>
    </table>
  ) : <p>No results found</p>;
};

export default TrackSearch;
